use super::geometry::{self, Point, Polygon, Ring};

const EPSILON: f64 = 1.0e-12;

pub fn earcut(polygon: &Polygon) -> Vec<u32> {
    match polygon.first() {
        Some(ring) => triangulate_ring(ring),
        None => Vec::new(),
    }
}

fn triangulate_ring(ring: &Ring) -> Vec<u32> {
    let vertex_count = ring.len();
    if vertex_count < 3 || vertex_count > u32::MAX as usize {
        return Vec::new();
    }

    let area = geometry::signed_area(ring);
    if area.abs() <= EPSILON {
        return Vec::new();
    }

    let is_ccw = area > 0.0;
    let mut prev = Vec::with_capacity(vertex_count);
    let mut next = Vec::with_capacity(vertex_count);
    let mut active = vec![true; vertex_count];

    for index in 0..vertex_count {
        prev.push(if index == 0 { vertex_count - 1 } else { index - 1 });
        next.push(if index + 1 == vertex_count { 0 } else { index + 1 });
    }

    let mut current = vertex_count - 1;
    let mut remaining = vertex_count;
    let mut stalled = 0usize;
    let mut triangles = Vec::with_capacity((vertex_count - 2) * 3);

    while remaining > 2 {
        let a = prev[current];
        let b = current;
        let c = next[current];

        if is_ear(a, b, c, ring, &active, is_ccw) {
            triangles.push(a as u32);
            triangles.push(b as u32);
            triangles.push(c as u32);

            active[b] = false;
            next[a] = c;
            prev[c] = a;
            remaining -= 1;

            if remaining <= 2 {
                break;
            }

            current = next[c];
            stalled = 0;
        } else {
            current = c;
            stalled += 1;
            if stalled > remaining {
                break;
            }
        }
    }

    triangles
}

fn is_ear(a: usize, b: usize, c: usize, ring: &Ring, active: &[bool], is_ccw: bool) -> bool {
    if !is_convex(ring[a], ring[b], ring[c], is_ccw) {
        return false;
    }

    for point_index in 0..ring.len() {
        if !active[point_index] || point_index == a || point_index == b || point_index == c {
            continue;
        }

        if point_in_triangle(ring[point_index], ring[a], ring[b], ring[c], is_ccw) {
            return false;
        }
    }

    true
}

fn is_convex(a: Point, b: Point, c: Point, is_ccw: bool) -> bool {
    let cross = cross(a, b, c);
    if is_ccw {
        cross > EPSILON
    } else {
        cross < -EPSILON
    }
}

fn point_in_triangle(point: Point, a: Point, b: Point, c: Point, is_ccw: bool) -> bool {
    let ab = cross(a, b, point);
    let bc = cross(b, c, point);
    let ca = cross(c, a, point);

    if is_ccw {
        ab >= -EPSILON && bc >= -EPSILON && ca >= -EPSILON
    } else {
        ab <= EPSILON && bc <= EPSILON && ca <= EPSILON
    }
}

fn cross(a: Point, b: Point, c: Point) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

