use std::f64::consts::PI;

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn regular_polygon(n: i32) -> Polygon {
    let vertex_count = i64::from(n).saturating_mul(3);
    let mut ring = Vec::new();

    if vertex_count > 0 {
        let count = vertex_count as usize;
        ring = Vec::with_capacity(count);
        let divisor = vertex_count as f64;

        for index in 0..count {
            let angle = 2.0 * PI * index as f64 / divisor;
            ring.push([angle.cos(), angle.sin()]);
        }
    }

    vec![ring]
}

pub fn signed_area(ring: &Ring) -> f64 {
    if ring.len() < 3 {
        return 0.0;
    }

    let mut area = 0.0;
    for index in 0..ring.len() {
        let next = (index + 1) % ring.len();
        area += ring[index][0] * ring[next][1] - ring[next][0] * ring[index][1];
    }

    area * 0.5
}

