pub fn parse_n<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let mut iter = args.into_iter();
    let _ = iter.next();

    match iter.next() {
        Some(value) => parse_atoi_like(&value),
        None => 1,
    }
}

fn parse_atoi_like(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i64;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let mut value = 0i64;
    let mut saw_digit = false;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        saw_digit = true;
        value = value
            .saturating_mul(10)
            .saturating_add(i64::from(bytes[index] - b'0'));
        index += 1;
    }

    if !saw_digit {
        return 0;
    }

    let signed = value.saturating_mul(sign);
    signed.clamp(i32::MIN as i64, i32::MAX as i64) as i32
}

